"""Request handling for the staged API rollout.

Older clients may use ``legacy_mode`` to bypass payload validation while the
new validation rules are rolled out.
"""


def _validate_request_data(data):
    """Raise an appropriate error if *data* is not a valid request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    if not all(isinstance(key, str) for key in data.keys()):
        raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload, then process it.

    Validation can be bypassed with ``legacy_mode=True`` for compatibility
    with older clients during the staged rollout.
    """
    if not legacy_mode:
        _validate_request_data(data)

    return process(data)

